function endGame(){state='over';document.getElementById('resultText').textContent=`You survived ${format(elapsed)} in the Wild Frontier.`;document.getElementById('resultTime').textContent=format(elapsed);document.getElementById('resultKills').textContent=kills;document.getElementById('resultLevel').textContent=player.level;document.getElementById('endOverlay').style.display='grid'}
function update(dt){worldTime+=dt;if(state!=='playing')return;elapsed+=dt;player.invuln=Math.max(0,player.invuln-dt);player.dash=Math.max(0,player.dash-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.fire-=dt;if(player.regen)player.hp=Math.min(player.maxHp,player.hp+player.regen*dt);
 let dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+stickVec.x,dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+stickVec.y,m=hyp(dx,dy);if(m>1){dx/=m;dy/=m}if(m>.08)player.angle=Math.atan2(dy,dx);let speed=player.speed*(player.dash>0?3.5:1);player.x+=dx*speed*dt;player.y+=dy*speed*dt;
 spawnTimer-=dt;let interval=Math.max(.22,1.05-elapsed*.006);if(spawnTimer<=0){spawnEnemy(elapsed>34&&Math.random()<.19?'brute':elapsed>15&&Math.random()<.3?'ranged':'scout');spawnTimer=interval*(.65+Math.random()*.7)}bossTimer-=dt;if(bossTimer<=0){spawnBoss();bossTimer=75}
 const target=nearest();if(player.fire<=0&&target){fireAt(target);player.fire=player.fireRate}
 for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.life<=0){bullets.splice(i,1);continue}for(let e of enemies){if(hyp(e.x-b.x,e.y-b.y)<e.r+b.r){e.hp-=b.damage;e.hit=.12;bullets.splice(i,1);if(e.hp<=0)killEnemy(e);break}}}
 for(let i=enemyShots.length-1;i>=0;i--){let b=enemyShots[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(hyp(b.x-player.x,b.y-player.y)<player.r+5&&player.invuln<=0){enemyShots.splice(i,1);damagePlayer(8);continue}if(b.life<=0)enemyShots.splice(i,1)}
 for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];e.hit=Math.max(0,e.hit-dt);e.attack-=dt;let ex=player.x-e.x,ey=player.y-e.y,d=hyp(ex,ey)||1;if(e.type==='ranged'&&d<270){if(d>195){e.x+=ex/d*e.speed*dt;e.y+=ey/d*e.speed*dt}else if(d<155){e.x-=ex/d*e.speed*dt;e.y-=ey/d*e.speed*dt}if(e.attack<=0){let a=Math.atan2(ey,ex);enemyShots.push({x:e.x,y:e.y,vx:Math.cos(a)*210,vy:Math.sin(a)*210,life:2});e.attack=2.2}}else{e.x+=ex/d*e.speed*dt;e.y+=ey/d*e.speed*dt}if(d<player.r+e.r-4&&player.invuln<=0){damagePlayer(Math.max(2,e.dmg-player.armor));player.invuln=.48;player.x-=ex/d*18;player.y-=ey/d*18}}
 for(let i=gems.length-1;i>=0;i--){let g=gems[i],d=hyp(g.x-player.x,g.y-player.y);if(d<player.pickup){let q=Math.min(1,(player.pickup-d)/player.pickup*.23+.08);g.x+=(player.x-g.x)*q;g.y+=(player.y-g.y)*q}if(d<player.r+g.r+4){gainXp(g.value);gems.splice(i,1)}}
