function damagePlayer(n){player.hp-=n;sound(100,.12,'sawtooth',.04);screenShake=Math.max(screenShake,7)}
function poly(points,fill,stroke='#15262b',width=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.lineWidth=width;ctx.strokeStyle=stroke;ctx.stroke()}}
function drawGround(camX,camY){ctx.fillStyle='#182a2d';ctx.fillRect(0,0,W,H);const size=90,ox=((W/2-camX)%size+size)%size,oy=((H/2-camY)%size+size)%size;ctx.strokeStyle='#25383a';ctx.lineWidth=1;ctx.beginPath();for(let x=ox;x<W;x+=size){ctx.moveTo(x,0);ctx.lineTo(x,H)}for(let y=oy;y<H;y+=size){ctx.moveTo(0,y);ctx.lineTo(W,y)}ctx.stroke();ctx.fillStyle='#203235';for(let x=ox-45;x<W;x+=size)for(let y=oy-45;y<H;y+=size){let wx=x+camX-W/2,wy=y+camY-H/2,v=Math.sin(wx*.036+wy*.021)*Math.cos(wy*.044);if(v>.92){ctx.beginPath();ctx.ellipse(x,y,rand(2,5),rand(1,3),v,0,Math.PI*2);ctx.fill()}}}
function drawMech(x,y,a,scale=1,isPlayer=false,color='#d1a153',hit=0){ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.scale(scale,scale);ctx.shadowColor=isPlayer?'#50e5e9':color;ctx.shadowBlur=isPlayer?17:5;ctx.fillStyle='#07101599';ctx.beginPath();ctx.ellipse(0,10,26,13,0,0,7);ctx.fill();ctx.shadowBlur=0;
 // articulated legs
 for(let side of [-1,1]){ctx.save();ctx.translate(-5,side*10);ctx.rotate(side*.12);ctx.fillStyle='#26373a';ctx.strokeStyle='#607779';ctx.lineWidth=1.5;ctx.beginPath();ctx.roundRect(-14,-5,24,10,3);ctx.fill();ctx.stroke();ctx.fillStyle=isPlayer?'#69d6d3':'#936343';ctx.fillRect(-15,-4,7,8);ctx.fillStyle='#17252a';ctx.fillRect(8,-6,9,12);ctx.restore()}
 // tail
 poly([[-13,0],[-26,-4],[-39,-2],[-32,3],[-20,5]],isPlayer?'#54a9a7':'#795b3b','#26363a',1);
 // body capsule and armor
 ctx.fillStyle=isPlayer?'#b9d1c2':color;ctx.strokeStyle=isPlayer?'#e4f0ce':'#f6ba75';ctx.lineWidth=1.3;ctx.beginPath();ctx.ellipse(0,0,20,11,0,0,Math.PI*2);ctx.fill();ctx.stroke();poly([[-5,-9],[11,-8],[20,-2],[18,4],[7,7],[-8,4]],isPlayer?'#6d9f91':'#85563c','#26373a');
 // cannon / shoulders
 ctx.fillStyle=isPlayer?'#d7e3c8':'#d99b58';ctx.fillRect(5,-13,15,5);ctx.fillRect(5,8,15,5);ctx.fillStyle='#25363a';ctx.fillRect(16,-14,8,3);ctx.fillRect(16,11,8,3);
 // head
 poly([[8,-7],[17,-7],[25,-3],[31,0],[24,3],[16,8],[9,6],[4,2]],isPlayer?'#e4e6c6':(hit?'#fff':color),'#203238',1.5);poly([[18,-7],[28,-4],[34,0],[28,2],[24,0]],isPlayer?'#b4cebd':'#e2af62','#26373a');ctx.fillStyle=isPlayer?'#4ef5f3':'#ff553e';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=9;ctx.beginPath();ctx.ellipse(24,0,3.8,1.6,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
 // markings
 ctx.strokeStyle=isPlayer?'#426a68':'#573e31';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-2,-5);ctx.lineTo(8,-5);ctx.moveTo(-1,5);ctx.lineTo(8,5);ctx.stroke();if(isPlayer){ctx.fillStyle='#54e4ed';ctx.fillRect(-8,-2,3,4)}ctx.restore()}
function drawEnemy(e,x,y){if(e.type==='boss'){ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(worldTime)*.08);ctx.globalAlpha=.16;ctx.strokeStyle='#ff5947';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,54+Math.sin(worldTime*3)*4,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;ctx.restore()}let a=Math.atan2(player.y-e.y,player.x-e.x);drawMech(x,y,a,e.type==='boss'?1.65:e.type==='brute'?1.28:1,false,e.color,e.hit);if(e.hp<e.maxHp){ctx.fillStyle='#070e11';ctx.fillRect(x-18,y-e.r-10,36,3);ctx.fillStyle=e.type==='boss'?'#ff574a':'#ffb45c';ctx.fillRect(x-18,y-e.r-10,36*e.hp/e.maxHp,3)}}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);const shake=screenShake?rand(-screenShake,screenShake):0,camX=player.x+shake,camY=player.y+shake;drawGround(camX,camY);const sx=x=>x-camX+W/2,sy=y=>y-camY+H/2;
 // subtle target-pickup range ring
 if(state==='title'){ctx.beginPath();ctx.arc(W/2,H/2,player.pickup,0,7);ctx.strokeStyle='#54e4ed0b';ctx.stroke()}
 for(const g of gems){let x=sx(g.x),y=sy(g.y),bob=Math.sin(worldTime*4+g.phase)*2;ctx.save();ctx.translate(x,y+bob);ctx.rotate(worldTime*1.5);ctx.shadowColor='#69ffff';ctx.shadowBlur=12;poly([[0,-g.r-2],[g.r,0],[0,g.r+2],[-g.r,0]],'#62e8e1','#d4ffff');ctx.restore()}
 for(const b of bullets){ctx.strokeStyle=b.crit?'#fff18b':'#67edf0';ctx.lineWidth=b.crit?4:2.5;ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=10;ctx.beginPath();ctx.moveTo(sx(b.x),sy(b.y));ctx.lineTo(sx(b.x)-b.vx*.025,sy(b.y)-b.vy*.025);ctx.stroke();ctx.shadowBlur=0}
 for(const b of enemyShots){ctx.fillStyle='#ff7558';ctx.shadowColor='#ff603e';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(sx(b.x),sy(b.y),5,0,7);ctx.fill();ctx.shadowBlur=0}
 for(const e of enemies)drawEnemy(e,sx(e.x),sy(e.y));
