 const targ=nearest();if(targ){ctx.strokeStyle='#ffac6377';ctx.lineWidth=1;ctx.beginPath();ctx.arc(sx(targ.x),sy(targ.y),targ.r+9,0,Math.PI*2);ctx.stroke()}
 if(player.invuln<=0||Math.floor(worldTime*20)%2===0)drawMech(W/2,H/2,player.angle,1,true);
 if(state==='playing'){let mapX=W-92,mapY=H-104;if(W>650){ctx.fillStyle='#071319aa';ctx.fillRect(mapX,mapY,72,72);ctx.strokeStyle='#77979a55';ctx.strokeRect(mapX,mapY,72,72);for(const e of enemies){let x=mapX+36+(e.x-player.x)*.045,y=mapY+36+(e.y-player.y)*.045;if(x>mapX&&x<mapX+72&&y>mapY&&y<mapY+72){ctx.fillStyle=e.type==='boss'?'#ff5147':'#e39e60';ctx.fillRect(x-1,y-1,e.type==='boss'?4:2,e.type==='boss'?4:2)}}ctx.fillStyle='#54e4ed';ctx.beginPath();ctx.arc(mapX+36,mapY+36,3,0,7);ctx.fill()}}
}
function loop(now){let dt=Math.min(.034,(now-last)/1000||0);last=now;update(dt);render();requestAnimationFrame(loop)}requestAnimationFrame(loop);

